    ('course-bili-bv1ctq8ydebf', 'course-bili-bv1ctq8ydebf', '100001', '0', 'BILI-OPS-002', 'course-category-operations', 'instructor-bili-3546595222096036', '私域运营零基础入门实操课，转行新媒体运营精品课', '18 讲完整课程 · 3 小时 54 分钟', '私域运营零基础入门实操课，转行新媒体运营精品课。共 18 讲，累计 3.9 小时，由 运营求职老唐 讲解，章节结构完整，可直接在课程播放器中观看。', '课程简介：私域运营零基础入门实操课，转行新媒体运营精品课 课程结构：共 3 章 18 讲，累计时长 3 小时 54 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握内容选题、脚本、拍摄与剪辑的完整生产链路","理解平台推荐机制与账号冷启动方法","搭建可复用的内容日历、数据复盘与投放模型","具备从零起号到商业变现的实战能力"]', '["零基础想做新媒体运营的职场人","需要提升账号数据的自媒体创作者","实体商家与品牌市场人员"]', '["有常用社交平台的真实使用经验","无需拍摄设备，手机即可完成练习"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/d462226c23ad925c921092d25826074c75c088df.png', '["运营营销","新媒体","增长实战","私域运营零基础入门实操课","转行新媒体运营精品课"]', 14077, 18, 11834, '4.3', 1587, 'BV1Ctq8YdEbf', NULL, NULL, NULL, 1, 0, 'standard', NULL, '运营求职老唐', 0, 'tenant', 'published', '2024-12-12T10:47:44.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
