VALUES
    ('course-bili-season-368009', 'course-bili-season-368009', '100001', '0', 'BILI-OPS-020', 'course-category-operations', 'instructor-bili-190038689', '企业如何搭建内容运营体系？【一小时完整课程】', '14 讲完整课程 · 11 小时 35 分钟', '如果你也是做运营的，你一定知道，运营本身的工作内容大致可以分成“用户运营”、“内容运营”、“活动运营”，那么品牌到底如何规划自身的内容运营体系呢？这个视频一节课教会你！', '课程简介：如果你也是做运营的，你一定知道，运营本身的工作内容大致可以分成“用户运营”、“内容运营”、“活动运营”，那么品牌到底如何规划自身的内容运营体系呢？这个视频一节课教会你！课程结构：共 1 章 14 讲，累计时长 11 小时 35 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握内容选题、脚本、拍摄与剪辑的完整生产链路","理解平台推荐机制与账号冷启动方法","搭建可复用的内容日历、数据复盘与投放模型","具备从零起号到商业变现的实战能力"]', '["零基础想做新媒体运营的职场人","需要提升账号数据的自媒体创作者","实体商家与品牌市场人员"]', '["有常用社交平台的真实使用经验","无需拍摄设备，手机即可完成练习"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/7e66b453575f860a7e9025eb5a4780ac85a2970b.jpg', '["运营营销","新媒体","增长实战","一小时完整课程"]', 41739, 14, 1678, '4.7', 985, 'BV1Pm4y1g7Hz', NULL, NULL, NULL, 1, 0, 'standard', NULL, '狐狸拆解', 0, 'tenant', 'published', '2023-10-09T05:10:39.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
